sites.original_assertion:
proc gdb-test {line var value} {
    global tests

    lappend tests($line) [list $var $value 0]
}

proc xfail-gdb-test {line var value} {
    global tests

    lappend tests($line) [list $var $value 1]
}

gdb_test_multiple "info sources" "$test" {
  -re "file1\\.txt.*file1\\.txt.*$gdb_prompt $" {
      fail "$test (file1.txt seen more than once)"
  }
  -re "file1\\.txt.*$gdb_prompt $" {
      pass "$test"
  }
}

gdb_test_multiple "info source" $test {
    -re "\r\nCompilation directory is .*\r\n$gdb_prompt $" {
	fail $test
    }
    -re "\r\nCurrent source file is dw2-compdir-oldgcc43.S\r\n.*\r\n$gdb_prompt $" {
	pass $test
    }
}

gdb_test_multiple "disassemble /${opt} main" "" {
	-re "Dump of assembler code for function main:\r\n" {
	    exp_continue
	}

	-re "^\[^\r\n\]+${srcfile3}:" {
	    exp_continue
	}

	-re "^(\\d+)\\s+\[^\r\n\]+\r\n" {
	    if { $linenum != -1 } {
		set lines($linenum) $addrs
		set addrs {}
	    }
	    set linenum $expect_out(1,string)
	    exp_continue
	}

	-re "^(?:=>)?\\s*($hex)\\s*\[^\r\n\]+\r\n" {
	    set address $expect_out(1,string)
	    lappend addrs $address
	    exp_continue
	}

	-re "^\\s*\r\n" {
	    exp_continue
	}

	-re "^End of assembler dump\\.\r\n" {
	    if { $linenum != -1 } {
		set lines($linenum) $addrs
		set linenum -1
		set addrs {}
	    }
	    exp_continue
	}

	-re "^$gdb_prompt $" {
	    # All done.
	}
    }

gdb_test_multiple "maint print objfiles $host_binfile" "" {
    -re "^maint print objfiles \[^\r\n\]*\r\n$gdb_prompt $" {
	setup_kfail "gdb/26797" *-*-*
    }
    -re -wrap "" {
    }
}

gdb_test_multiple "stepi" "stepi ${i}" {
	-re "${srcfile3} : 19 .*${gdb_prompt} " {
	    set found_line_19 1
	    set keep_going 1
	}

	-re "${srcfile3} : 20 .*${gdb_prompt} " {
	    set found_line_20 1
	}

	-re "${srcfile4} : 22 .*${gdb_prompt} " {
	    # Not left line 22 yet.
	    set keep_going 1
	}
    }

gdb_test_multiple $test $test {
    -re "Symbol \"break_at\" is at (0x\[0-9a-f\]+) in .*\r\n$gdb_prompt $" {
	set break_at $expect_out(1,string)
	pass $test
    }
}

gdb_test_multiple "stepi" "stepi until line_label_2" {
		-re "main, set var to 99.*$gdb_prompt" {
		    set line_changed 0
		}
		-re "main, set var to 0.*$gdb_prompt " {
		    set line_changed 1
		}
	    }

gdb_test_multiple "stepi" "stepi until line_label_5" {
		-re "main, set var to 0.*$gdb_prompt" {
		    set line_changed 0
		}
		-re "main end.*$gdb_prompt " {
		    set line_changed 1
		}
	    }

gdb_test_multiple $test $test {
    -re ":\[ \t\]*0x341255aa\r\n$gdb_prompt $" {
	# little endian
	pass $test
	gdb_test "p/x implicit4to2" " = 0x2211"
	gdb_test "p/x implicit4to4" " = 0x44332211"
    }
    -re ":\[ \t\]*0xaa551234\r\n$gdb_prompt $" {
	# big endian
	pass $test
	gdb_test "p/x implicit4to2" " = 0x1122"
	gdb_test "p/x implicit4to4" " = 0x11223344"
    }
    -re ":\[ \t\]*0x\[0-9a-f\]{8}\r\n$gdb_prompt $" {
	unsupported $test
    }
}

gdb_test_multiple "maint info line-table gdb.dwarf2/dw2-ranges-base.c" \
    "count END markers in line table" {
	-re "^$decimal\[ \t\]+$decimal\[ \t\]+$hex\[ \t\]+$hex\(\[ \t\]+Y\)? *\r\n" {
	    if { $prev != -1 } {
		gdb_assert "$prev == 1" \
		    "prev of normal entry at $seq_count is end marker"
	    }
	    set prev 0
	    incr seq_count
	    exp_continue
	}
	-re "^$decimal\[ \t\]+END\[ \t\]+$hex\[ \t\]+$hex\(\[ \t\]+Y\)? *\r\n" {
	    if { $prev != -1 } {
		gdb_assert "$prev == 0" \
		    "prev of end marker at $seq_count is normal entry"
	    }
	    set prev 1
	    incr seq_count
	    incr end_seq_count
	    exp_continue
	}
	-re "^\r\n" {
	    # Empty lines between tables.
	    exp_continue
	}
	-re "^$gdb_prompt $" {
	    gdb_assert [expr $end_seq_count == 3] $gdb_test_name
	}
	-re ".*linetable: \\(\\(struct linetable \\*\\) 0x0\\):\r\nNo line table.\r\n" {
	    exp_continue
	}
	-re ".*linetable: \\(\\(struct linetable \\*\\) $hex\\):\r\nINDEX\[ \t\]+LINE\[ \t\]+REL-ADDRESS\[ \t\]+UNREL-ADDRESS\[ \t\]+IS-STMT\[ \t\]PROLOGUE-END\[ \t\]EPILOGUE-BEGIN *\r\n" {
	    exp_continue
	}
    }

gdb_test_multiple "continue" $test {
	    -re "Breakpoint \\d+, foo \\(\\).*foo prologue.*${gdb_prompt}" {
		pass $test
		gdb_test "step" \
			 "foo bar call .*" \
			 "step to call of bar after landing on prologue"
	    }
	    -re "Breakpoint \\d+, foo \\(\\).*foo bar call.*${gdb_prompt}" {
		pass $test
	    }
	}

gdb_test_multiple "step" $test {
		-re "foo(_low)? \\(\\).*\{.*foo_cold prologue.*${gdb_prompt}" {
		    pass $test
		    gdb_test "step" \
			     "foo \\(\\).*baz \\(\\);.*foo_cold baz call.*" \
			     "step to baz call in foo_cold"

		}
		-re "foo(_cold)? \\(\\).*baz \\(\\);.*foo_cold baz call.*${gdb_prompt}" {
		    pass $test
		}
	    }

gdb_test_multiple "maint info line-table" \
	    "check END marker at index $index in $expected_symtab" {
	    -re "^symtab: \[^\r\n\]+/($::testfile-$::decimal.c) \\(\\(\[^\r\n\]+\r\n" {
		set symtab $expect_out(1,string)
		exp_continue
	    }
	    -re "^${index}\\s+END\\s+0x0*$addr\\s+$::hex\\s+Y\\s*\r\n" {
		if { $symtab eq $expected_symtab } {
		    set saw_line true
		}
		exp_continue
	    }
	    -re "^$::gdb_prompt $" {
		gdb_assert $saw_line $gdb_test_name
	    }
	    -re "^\[^\r\n\]*\r\n" {
		exp_continue
	    }
	}

gdb_test_multiple "file $host_binfile" "file command" {
    -re "\r\nReading symbols from \[^\r\n\]*\\.\\.\\." {
	exp_continue
    }
    -re "^\r\nDuring symbol reading: location description stack underflow" {
	set w1 1
	exp_continue
    }
    -re "^\r\nDuring symbol reading: location description stack overflow" {
	set w2 1
	exp_continue
    }
    -re -wrap "" {
	pass $gdb_test_name
    }
}

gdb_test_multiple "maint with dwarf synchronous on -- sharedlibrary [file tail $lib_path]" "load shared library" {
	    -re -wrap $complaint_re {
		set have_complaint 1
	    }
	    -re -wrap "" {
	    }
	}

gdb_test_multiple "ptype foo" "" {
    -re -wrap "type = int" {
	set cu1_expanded 1
	pass $gdb_test_name
    }
}

gdb_test_multiple "maint print symbols -source cu2" "CU addr found" {
    -re -wrap $cu2_blockvector_re {
	set addr $expect_out(1,string)
	if { $addr eq "0x0" } {
	    fail "$gdb_test_name (Found 0x0)"
	} else {
	    gdb_test "info symbol $addr" "main in section .*" \
		$gdb_test_name
	}
    }
}

gdb_test_multiple "$cmd $output_dir" $cmd {
    -re -wrap "Cannot use an index to create the index.*" {
	unsupported $gdb_test_name
    }
    -re "^$cmd \[^\r\n\]*\r\n$gdb_prompt $" {
	pass $gdb_test_name
    }
}

gdb_test_multiple "$cmd $output_dir" $cmd {
    -re -wrap "Cannot use an index to create the index.*" {
	unsupported $gdb_test_name
    }
    -re "^$cmd \[^\r\n\]*\r\n$gdb_prompt $" {
	pass $gdb_test_name
    }
}

gdb_test_multiple $cmd "try to save gdb index" {
    -re -wrap $have_index_re {
	if { $have_index != "" || $readnow_p } {
	    unsupported $gdb_test_name
	} else {
	    fail $gdb_test_name
	}
    }
    -re -wrap $no_debug_re {
	pass $gdb_test_name
    }
    -re -wrap "^" {
	pass $gdb_test_name
    }
}

gdb_test_multiple "maint print objfile $binfile" "check we can generate an index" {
    -re "\r\n\\.gdb_index: version ${decimal}(?=\r\n)" {
	set has_index true
	gdb_test_lines "" $gdb_test_name ".*"
    }
    -re "\r\n\\.debug_names: exists(?=\r\n)" {
	set has_index true
	gdb_test_lines "" $gdb_test_name ".*"
    }
    -re "\r\n(Cooked index in use:|Psymtabs)(?=\r\n)" {
	set can_dump_index true
	gdb_test_lines "" $gdb_test_name ".*"
    }
    -re -wrap "" {
    }
}

gdb_test_multiple $cmd $test {
    -re ^$cmd_re {
	exp_continue
    }
    -re "gdb_index.*${gdb_prompt} $" {
	set testfile_with_index $testfile
	set binfile_with_index [standard_output_file $testfile_with_index]
	set host_binfile_with_index [gdb_remote_download host $binfile]
    }
    -re "debug_names.*${gdb_prompt} $" {
	set testfile_with_index $testfile
	set binfile_with_index [standard_output_file $testfile_with_index]
	set host_binfile_with_index [gdb_remote_download host $binfile]
    }
    -re "(Psymtabs|Cooked).*${gdb_prompt} $" {
	lassign [local_add_gdb_index $binfile] binfile_with_index host_binfile_with_index
	set testfile_with_index [file tail $binfile_with_index]
	if { ${binfile_with_index} == "" } {
	    return -1
	}
    }
    -re ".*${gdb_prompt} $" {
	fail "unrecognized symbol reader"
    }
}

gdb_test_multiple "" "stopped at mymain" {
    -re -wrap "Temporary breakpoint .* mymain.*" {
	pass $gdb_test_name
    }
    -re -wrap "Temporary breakpoint .* main.*" {
	if { $have_index } {
	    setup_kfail "gdb/24549" *-*-*
	}
	fail $gdb_test_name
    }
}

gdb_test_multiple "break $func" "place breakpoint" {
	    -re -wrap "Breakpoint $::decimal at ($::hex)(?:: \[^\r\n\]+)?" {
		set addr $expect_out(1,string)
		pass $gdb_test_name
	    }
	}

gdb_test_multiple "print a.i" \
	"print a.i with optimized out piece" {
	    -re "warning: some bits in computed object" {
		fail "print a.i with optimized out piece"
	    }
	    -re " = 7" {
		pass "print a.i with optimized out piece"
	    }
	}

proc gdb-test {line var value} {
    global tests

    lappend tests($line) [list $var $value 0]
}

proc xfail-gdb-test {line var value {arch_pattern ""}} {
    global tests

    set flag 1
    if {$arch_pattern != ""} {
	if {! [istarget $arch_pattern]} {
	    set flag 0
	}
    }

    lappend tests($line) [list $var $value $flag]
}
